/* eslint-disable @typescript-eslint/no-unsafe-declaration-merging */
import { css, CSSResultGroup, html, nothing, PropertyValues } from "lit";
import { property, state } from "lit/decorators.js";

import {
  AttachInternals,
  customElement,
  ConstraintValidation,
  DesignToken,
  Dirty,
  Disabled,
  FormAssociated,
  formValue,
  Required,
  RequiredConstraintValidation,
  Role,
  Touched,
  registerStyleSheet,
  waitForUpdate,
} from "@m3e/web/core";

import { ListKeyManager, ListManager } from "@m3e/web/core/a11y";
import { M3eDirectionality } from "@m3e/web/core/bidi";
import { FormFieldControl } from "@m3e/web/form-field";
import type { M3eOptionElement } from "@m3e/web/option";

import { M3eChipSetElement } from "./ChipSetElement";
import { M3eInputChipElement } from "./InputChipElement";
import { InputChipSetChangeEventDetail } from "./InputChipSetChangeEventDetail";

/**
 * A container that transforms user input into a cohesive set of interactive chips, supporting entry, editing, and removal of discrete values.
 *
 * @description
 * The `m3e-input-chip-set` component enables users to input, display, and manage a collection of discrete
 * values as input chips. Designed for expressive, accessible forms, it supports keyboard navigation, validation,
 * and seamless integration with form controls. This component is ideal for capturing user-generated tags,
 * keywords, or selections in a visually consistent and interactive manner.
 *
 * @example
 * Place an input chip set in a form field and provide an input through its `input` slot. Import `@m3e/web/form-field` for the form field.
 *
 * ```html
 * <m3e-form-field>
 *   <label slot="label" for="keywords">Keywords</label>
 *   <m3e-input-chip-set aria-label="Enter keywords">
 *     <input id="keywords" slot="input" placeholder="New keyword..." />
 *   </m3e-input-chip-set>
 * </m3e-form-field>
 * ```
 *
 * @example
 * Prepopulate an input chip set with removable input chips. Import `@m3e/web/form-field` for the form field.
 *
 * ```html
 * <m3e-form-field>
 *   <label slot="label" for="keywords">Keywords</label>
 *   <m3e-input-chip-set aria-label="Enter keywords">
 *     <m3e-input-chip removable>Design</m3e-input-chip>
 *     <m3e-input-chip removable>Accessibility</m3e-input-chip>
 *     <m3e-input-chip removable>Motion</m3e-input-chip>
 *     <input id="keywords" slot="input" placeholder="New keyword..." />
 *   </m3e-input-chip-set>
 * </m3e-form-field>
 * ```
 *
 * @example
 * Use `max-chips` to limit the chips shown while the input is not focused. Import `@m3e/web/form-field` for the form field.
 *
 * ```html
 * <m3e-form-field>
 *   <label slot="label" for="keywords">Keywords</label>
 *   <m3e-input-chip-set aria-label="Enter keywords" max-chips="1">
 *     <m3e-input-chip removable>Design</m3e-input-chip>
 *     <m3e-input-chip removable>Accessibility</m3e-input-chip>
 *     <m3e-input-chip removable>Motion</m3e-input-chip>
 *     <input id="keywords" slot="input" placeholder="New keyword..." />
 *   </m3e-input-chip-set>
 * </m3e-form-field>
 * ```
 *
 * @example
 * Use `disabled` to disable the input chip set, its input, and its chips. Import `@m3e/web/form-field` for the form field.
 *
 * ```html
 * <m3e-form-field>
 *   <label slot="label" for="keywords">Keywords</label>
 *   <m3e-input-chip-set aria-label="Enter keywords" disabled>
 *     <m3e-input-chip removable>Design</m3e-input-chip>
 *     <m3e-input-chip removable>Accessibility</m3e-input-chip>
 *     <m3e-input-chip removable>Motion</m3e-input-chip>
 *     <input id="keywords" slot="input" placeholder="New keyword..." />
 *   </m3e-input-chip-set>
 * </m3e-form-field>
 * ```
 *
 * @tag m3e-input-chip-set
 *
 * @slot - Renders the chips of the set.
 * @slot input - Renders the input element used to add new chips to the set.
 *
 * @attr disabled - Whether the element is disabled.
 * @attr name - The name that identifies the element when submitting the associated form.
 * @attr required - Whether a value is required for the element.
 * @attr vertical - Whether the element is oriented vertically.
 * @attr max-chips - Maximum number of chips to display when not focused. When focused, all chips are displayed.
 *
 * @fires change - Dispatched when a chip is added to, or removed from, the set.
 *
 * @cssprop --m3e-chip-set-spacing - The spacing (gap) between chips in the set.
 */
@customElement("m3e-input-chip-set")
export class M3eInputChipSetElement
  extends RequiredConstraintValidation(
    Required(
      ConstraintValidation(Dirty(Touched(FormAssociated(Disabled(AttachInternals(Role(M3eChipSetElement, "grid"))))))),
      false,
    ),
  )
  implements FormFieldControl
{
  static {
    registerStyleSheet(css`
      m3e-input-chip-set [slot="input"]::placeholder {
        user-select: none;
        color: currentColor;
        transition: opacity ${DesignToken.motion.duration.extraLong1};
      }
      m3e-input-chip-set:not(:focus-within) [slot="input"]::placeholder {
        opacity: 0;
        transition: 0s;
      }
      m3e-input-chip-set:hover [slot="input"]::placeholder {
        transition: 0s;
      }
      @media (prefers-reduced-motion) {
        m3e-input-chip-set [slot="input"]::placeholder {
          transition: none !important;
        }
      }
    `);
  }

  /** The styles of the element. */
  static override styles: CSSResultGroup = [
    M3eChipSetElement.styles,
    css`
      ::slotted([slot="input"]) {
        outline: unset;
        border: unset;
        background-color: transparent;
        box-shadow: none;
        font-family: inherit;
        font-size: inherit;
        line-height: initial;
        letter-spacing: inherit;
        color: var(--_form-field-input-color, inherit);
        flex: 1 1 auto;
        min-width: 0;
        padding: unset;
      }
      ::slotted(m3e-input-chip) {
        min-width: 0;
      }
      span[role="row"],
      span[role="gridcell"] {
        display: contents;
      }
      .overflow {
        display: flex;
        flex: none;
        align-items: center;
        justify-content: center;
        font-size: var(--m3e-chip-label-text-font-size, ${DesignToken.typescale.standard.label.large.fontSize});
        font-weight: var(--m3e-chip-label-text-font-weight, ${DesignToken.typescale.standard.label.large.fontWeight});
        line-height: var(--m3e-chip-label-text-line-height, ${DesignToken.typescale.standard.label.large.lineHeight});
        letter-spacing: var(--m3e-chip-label-text-tracking, ${DesignToken.typescale.standard.label.large.tracking});
      }
      :host(:not(:disabled)) .overflow {
        color: var(--m3e-chip-label-text-color, ${DesignToken.color.onSurface});
      }
      :host(:disabled) .overflow {
        color: color-mix(
          in srgb,
          var(--m3e-chip-disabled-label-text-color, ${DesignToken.color.onSurface})
            var(--m3e-chip-disabled-label-text-opacity, 38%),
          transparent
        );
      }
    `,
  ];

  /** @private */ #directionalitySubscription?: () => void;
  /** @private */ readonly #inputChangeHandler = () => this.#handleInputChange();
  /** @private */ readonly #inputKeyDownHandler = (e: KeyboardEvent) => this.#handleInputKeyDown(e);
  /** @private */ readonly #focusHandler = () => this.#handleFocus();
  /** @private */ readonly #focusInHandler = () => this.#handleFocusIn();
  /** @private */ readonly #focusOutHandler = () => this.#handleFocusOut();
  /** @private */ readonly #chipRemoveHandler = (e: Event) => this.#handleChipRemove(e);
  /** @private */ readonly #chipClickHandler = (e: Event) => this.#handleChipClick(e);

  /** @private */ readonly #listManager = new ListManager<M3eInputChipElement>();
  /** @private */ readonly #listKeyManager = new ListKeyManager<HTMLElement>()
    .onActiveItemChange(() => this.#listKeyManager.activeItem?.focus())
    .withHomeAndEnd()
    .withSkipPredicate((x) => !x.hasAttribute("tabindex"))
    .withDirectionality(M3eDirectionality.current);

  /** @private */ #ignoreInputChange = false;
  /** @private */ #input: HTMLInputElement | null = null;
  /** @private */ #tabindex = 0;

  /** @private */ @state() private _focused = false;

  /**
   * Maximum number of chips to display when not focused. When focused, all chips are displayed.
   * @default null
   */
  @property({ attribute: "max-chips", type: Number }) maxChips: number | null = null;

  /** The chips of the set. */
  get chips(): readonly M3eInputChipElement[] {
    // NOTE: query is used instead of the internal list management due to
    // validating required state on change to support form-field integration.
    return [...this.querySelectorAll("m3e-input-chip")];
  }

  /** The values of the set. */
  get value(): readonly string[] | null {
    const values = this.chips.filter((x) => !x.disabled).map((x) => x.value);
    return values.length == 0 ? null : values;
  }

  /** @inheritdoc @internal */
  override get [formValue]() {
    const values = this.value;
    if (!values) return null;
    const data = new FormData();
    for (const value of values) {
      data.append(this.name, value);
    }
    return data;
  }

  /** @inheritdoc */
  get shouldLabelFloat(): boolean {
    return this.chips.length > 0;
  }

  /** @inheritdoc */
  onContainerClick(): void {
    this.#input?.focus();
  }

  /** @inheritdoc */
  override connectedCallback(): void {
    super.connectedCallback();

    if (!customElements.get("m3e-form-field")) {
      customElements.whenDefined("m3e-form-field").then(() => {
        this.closest("m3e-form-field")?.notifyControlStateChange();
      });
    } else {
      this.closest("m3e-form-field")?.notifyControlStateChange();
    }

    this.#tabindex = Number.parseInt(this.getAttribute("tabindex") ?? "0");
    this.addEventListener("focus", this.#focusHandler);
    this.addEventListener("focusin", this.#focusInHandler);
    this.addEventListener("focusout", this.#focusOutHandler);

    this.#directionalitySubscription = M3eDirectionality.observe(
      () => (this.#listKeyManager.directionality = M3eDirectionality.current),
    );
  }

  /** @inheritdoc */
  override disconnectedCallback(): void {
    super.disconnectedCallback();

    this.removeEventListener("focus", this.#focusHandler);
    this.removeEventListener("focusin", this.#focusInHandler);
    this.removeEventListener("focusout", this.#focusOutHandler);

    this.#directionalitySubscription?.();
  }

  /** @inheritdoc */
  protected override firstUpdated(_changedProperties: PropertyValues): void {
    super.firstUpdated(_changedProperties);

    if (!this.hasAttribute("tabindex")) {
      this.setAttribute("tabindex", `${this.#tabindex}`);
    }
  }

  /** @inheritdoc */
  protected override update(changedProperties: PropertyValues<this>): void {
    super.update(changedProperties);

    if (changedProperties.has("vertical")) {
      this.ariaOrientation = null;
    }
    if (changedProperties.has("disabled")) {
      this.#listManager.items.forEach((x) => (x.disabled = this.disabled));
      if (this.#input) {
        this.#input.disabled = this.disabled;
      }
    }
  }

  /** @inherit */
  protected override updated(_changedProperties: PropertyValues): void {
    super.updated(_changedProperties);

    if (_changedProperties.has("maxChips") || _changedProperties.has("_focused")) {
      this.#updateChipVisibility();
    }
  }

  /** @inheritdoc */
  protected override render(): unknown {
    return html`<slot @keydown=${this.#handleKeyDown} @slotchange=${this.#handleSlotChange}></slot>
      ${!this._focused && this.maxChips && this.chips.length > this.maxChips
        ? html`<div class="overflow">+${this.chips.length - this.maxChips}</div>`
        : nothing}
      <span role="row">
        <span role="gridcell"><slot name="input" @slotchange=${this.#handleInputSlotChange}></slot></span>
      </span> `;
  }

  /** @private */
  #handleKeyDown(e: KeyboardEvent): void {
    this.#listKeyManager.onKeyDown(e);
  }

  /** @private */
  async #handleSlotChange(): Promise<void> {
    const { added, removed } = this.#listManager.setItems([...this.querySelectorAll("m3e-input-chip")]);

    for (const chip of added) {
      await waitForUpdate(chip);
      if (this.disabled) {
        chip.disabled = true;
      }
      chip.addEventListener("remove", this.#chipRemoveHandler);
      chip.cell.addEventListener("click", this.#chipClickHandler);
    }

    removed.forEach((x) => {
      x.removeEventListener("remove", this.#chipRemoveHandler);
      x.cell.removeEventListener("click", this.#chipClickHandler);
    });

    this.#listKeyManager.setItems(
      this.#listManager.items.flatMap((x) => (x.removeButton ? [x.cell, x.removeButton] : [x.cell])),
    );
    if (!this.#listKeyManager.activeItem) {
      this.#listKeyManager.updateActiveItem(this.#listKeyManager.items.find((x) => x.hasAttribute("tabindex")));
    }

    this.#updateChipVisibility();
  }

  /** @private */
  #handleInputSlotChange(): void {
    const input = this.querySelector("input");
    if (this.#input) {
      this.#input.removeEventListener("change", this.#inputChangeHandler);
      this.#input.removeEventListener("keydown", this.#inputKeyDownHandler);
    }

    this.#input = input;
    if (this.#input) {
      this.#input.disabled = this.disabled;
      this.#input.addEventListener("change", this.#inputChangeHandler);
      this.#input.addEventListener("keydown", this.#inputKeyDownHandler);

      const property = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, "value")!;
      Object.defineProperty(input, "value", {
        get: () => property.get?.call(input),
        set: (value: string) => {
          property.set?.call(input, value);
          if (this.#input === input && !this.#ignoreInputChange) {
            this.#handleInputChange();
          }
        },
      });
    }
  }

  /** @private */
  #handleFocus(): void {
    setTimeout(() => (this.#listKeyManager.activeItem ?? this.#input)?.focus());
  }

  /** @private */
  #handleFocusIn(): void {
    this.setAttribute("tabindex", "-1");
    this._focused = true;
  }

  /** @private */
  #handleFocusOut(): void {
    this.setAttribute("tabindex", `${this.#tabindex}`);
    this._focused = false;
  }

  /** @private */
  #handleChipRemove(e: Event): void {
    const chip = <M3eInputChipElement>e.target;
    const index = this.#listManager.items.indexOf(chip);
    const nextChip = this.#listManager.items.find((x, y) => y > index && !x.disabled && x.removable);

    chip.remove();

    this.#listKeyManager.setActiveItem(this.#listKeyManager.items.find((x) => x === nextChip?.removeButton));
    if (!this.#listKeyManager.activeItem) {
      this.#input?.focus();
    }

    this.dispatchEvent(
      new CustomEvent<InputChipSetChangeEventDetail>("change", {
        bubbles: true,
        detail: { type: "remove", value: chip.value, chip: chip },
      }),
    );
  }

  /** @private */
  #handleChipClick(e: Event): void {
    this.#listKeyManager.updateActiveItem(e.composedPath().find((x) => x instanceof M3eInputChipElement)?.cell);
  }

  /** @private */
  async #handleInputChange(): Promise<void> {
    if (!this.#input) return;
    const value = this.#input.value;
    if (!value) return;

    // Determine the value that corresponds to the new chip based on options provided
    // by a corresponding autocomplete.

    let matchedOption: M3eOptionElement | null = null;

    const options = (this.getRootNode() as ParentNode)
      .querySelector(`m3e-autocomplete[for="${this.#input.id}"]`)
      ?.querySelectorAll("m3e-option");

    if (options) {
      for (const option of options) {
        // Label is used as the input's value when supplied by an autocomplete.
        if (option.label === value) {
          matchedOption = option;
          break;
        }
      }
    }

    // Prevent duplicate chips from being added.

    let newChip: M3eInputChipElement | null = null;
    if (!this.chips.some((x) => x.value === (matchedOption?.value ?? value))) {
      newChip = document.createElement("m3e-input-chip");
      newChip.removable = true;
      newChip.appendChild(document.createTextNode(value));
      if (matchedOption) {
        newChip.value = matchedOption.value;
      }

      this.appendChild(newChip);
      await waitForUpdate(newChip);
    }

    if (this.#input) {
      try {
        this.#ignoreInputChange = true;
        this.#input.value = "";
      } finally {
        this.#ignoreInputChange = false;
      }
    }

    if (newChip) {
      this.dispatchEvent(
        new CustomEvent<InputChipSetChangeEventDetail>("change", {
          bubbles: true,
          detail: { type: "add", value: value, chip: newChip },
        }),
      );
    }
  }

  /** @private */
  #handleInputKeyDown(e: KeyboardEvent): void {
    if (e.key === "Backspace" && !this.#input?.value) {
      const item = [...this.#listManager.items]
        .reverse()
        .find((x) => !x.disabled && !x.disabledInteractive && x.removable);
      if (item) {
        item.dispatchEvent(new Event("remove"));
      }
    }
  }

  /** @private */
  #updateChipVisibility(): void {
    this.chips.forEach((chip, i) => (chip.hidden = !this._focused && this.maxChips != null && i >= this.maxChips));
  }
}

interface M3eInputChipSetElementEventMap extends HTMLElementEventMap {
  change: CustomEvent<InputChipSetChangeEventDetail>;
}

export interface M3eInputChipSetElement {
  addEventListener<K extends keyof M3eInputChipSetElementEventMap>(
    type: K,
    listener: (this: M3eInputChipSetElement, ev: M3eInputChipSetElementEventMap[K]) => void,
    options?: boolean | AddEventListenerOptions,
  ): void;

  addEventListener(
    type: string,
    listener: EventListenerOrEventListenerObject,
    options?: boolean | AddEventListenerOptions,
  ): void;

  removeEventListener<K extends keyof M3eInputChipSetElementEventMap>(
    type: K,
    listener: (this: M3eInputChipSetElement, ev: M3eInputChipSetElementEventMap[K]) => void,
    options?: boolean | EventListenerOptions,
  ): void;

  removeEventListener(
    type: string,
    listener: EventListenerOrEventListenerObject,
    options?: boolean | EventListenerOptions,
  ): void;
}

declare global {
  interface HTMLElementTagNameMap {
    "m3e-input-chip-set": M3eInputChipSetElement;
  }
}
